package br.com.erp;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.test.context.TestPropertySource;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@TestPropertySource(properties="erp.fiscal.master-key=AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=")
class FiscalConfigurationTest extends ApiTestSupport {
 String auth;UUID branch;
 @BeforeEach void setup()throws Exception{auth=token(company);branch=db.queryForObject("SELECT id FROM branch WHERE tenant_id=?",UUID.class,tenant);}
 Map<String,Object> issuer(){var m=new LinkedHashMap<String,Object>();m.put("cnpj","12345678000195");m.put("legalName","Emitente exclusivamente de teste");m.put("stateRegistration","123456789");m.put("taxRegime","1");m.put("state","GO");m.put("municipalityCode","5208707");m.put("municipality","Goiania");m.put("street","Rua de teste");m.put("number","1");m.put("district","Teste");m.put("postalCode","74000000");m.put("nfeSeries",1);m.put("nfceSeries",1);return m;}
 int save(Map<String,Object> body)throws Exception{return http.perform(put("/api/v1/fiscal/configuration").header("Authorization","Bearer "+auth).contentType("application/json").content(json.writeValueAsString(body))).andReturn().getResponse().getStatus();}
 @Test void configurationIsVersionedIdempotentAndEnvironmentScoped()throws Exception{var body=new LinkedHashMap<String,Object>(Map.of("requestId",UUID.randomUUID(),"branchId",branch,"environment","HOMOLOGATION","version",0,"issuer",issuer()));assertEquals(200,save(body));assertEquals(200,save(body));assertEquals(1,db.queryForObject("SELECT version FROM fiscal_establishment WHERE tenant_id=?",Long.class,tenant));body.put("requestId",UUID.randomUUID());assertEquals(409,save(body));var view=getApi("/api/v1/fiscal/configuration?branchId="+branch+"&environment=HOMOLOGATION",auth,200);assertTrue(view.get("configured").asBoolean());assertFalse(view.has("credential_ciphertext"));assertFalse(view.get("certificateConfigured").asBoolean());assertFalse(getApi("/api/v1/fiscal/configuration?branchId="+branch+"&environment=PRODUCTION",auth,200).get("configured").asBoolean());}
 @Test void configurationCannotBeReadAcrossTenantsOrAfterRevocation()throws Exception{String other="other-"+UUID.randomUUID();provisioning.create("Outra",other,"Admin","admin@example.com",password);getApi("/api/v1/fiscal/configuration?branchId="+branch+"&environment=HOMOLOGATION",token(other),404);db.update("DELETE FROM user_permission WHERE tenant_id=? AND permission='fiscal:read'",tenant);getApi("/api/v1/fiscal/configuration?branchId="+branch+"&environment=HOMOLOGATION",auth,403);}
 @Test void invalidA1DoesNotPersistSecretsOrConsumeVersion()throws Exception{assertEquals(200,save(new LinkedHashMap<>(Map.of("requestId",UUID.randomUUID(),"branchId",branch,"environment","HOMOLOGATION","version",0,"issuer",issuer()))));http.perform(put("/api/v1/fiscal/certificate").header("Authorization","Bearer "+auth).contentType("application/json").content(json.writeValueAsString(Map.of("requestId",UUID.randomUUID(),"branchId",branch,"environment","HOMOLOGATION","version",1,"certificateBase64",Base64.getEncoder().encodeToString("not-a-certificate".getBytes()),"password","test-password")))).andExpect(status().isBadRequest());assertEquals(1,db.queryForObject("SELECT version FROM fiscal_establishment WHERE tenant_id=?",Long.class,tenant));assertNull(db.queryForObject("SELECT credential_ciphertext FROM fiscal_establishment WHERE tenant_id=?",String.class,tenant));}
}
